const fs = require('fs');
const sysPath = require('path');
const os = require('os');
const { promisify } = require('util');

const stat = promisify(fs.stat);
const readdir = promisify(fs.readdir);

// Real check for macOS
const isMacos = process.platform === 'darwin' && os.type() === 'Darwin';

module.exports = {
  isMacos,
  stat,
  readdir,
};
